#!/usr/bin/env bash
# Generated by orca-setup from .orca-setup.json; change that file or the kit, not this one.
# Fresh-worktree gate after a merge: create a throwaway worktree from main through Orca (so
# setup runs), run the fresh-checkout checks, remove it, and confirm it is gone. Run from the main
# checkout in an Orca terminal: `exec ./scripts/orca/verify-main.sh <NNN>`.
# Prints "VERIFY OK" or "VERIFY FAILED: <step>"; output goes to .scratch/tmp/verify-main.log.
set -uo pipefail
cd "$(dirname "$0")/../.." || exit 1

plan=${1:?usage: scripts/orca/verify-main.sh <plan number>}
if [ "$(git rev-parse --absolute-git-dir)" != "$(git rev-parse --path-format=absolute --git-common-dir)" ]; then
  echo "verify-main: run it from the main checkout" >&2
  exit 1
fi

repo=$PWD
name="${plan}-verify"
wt="$repo/.worktrees/$(basename "$repo")/$name"
mkdir -p .scratch/tmp
log="$repo/.scratch/tmp/verify-main.log"
: > "$log"

fail() { echo "VERIFY FAILED: $1" | tee -a "$log"; echo "log: $log"; exit 1; }

echo "=== create $name"
orca worktree create --name "$name" --repo "path:$repo" --base-branch main --setup run --json >> "$log" 2>&1 \
  || fail "create"

# Wait for setup (up to 10 minutes).
for _ in $(seq 1 300); do
  [ -e "$wt/node_modules/.bin/astro" ] && break
  sleep 2
done
[ -e "$wt/node_modules/.bin/astro" ] || fail "setup did not finish"

result=0
echo "=== test"
(cd "$wt" && npm test) >> "$log" 2>&1 || { echo "=== test failed"; result=1; }

echo "=== remove $name"
orca worktree rm --worktree "path:$wt" --run-hooks --json >> "$log" 2>&1
for _ in $(seq 1 15); do
  [ -d "$wt" ] || break
  sleep 2
done
# Finder can write .DS_Store files while the folder is deleted ("Directory not empty"). Once git
# no longer lists the worktree, what is left is a plain folder: delete it.
if [ -d "$wt" ]; then
  if git worktree list --porcelain | grep -qx "worktree $wt"; then
    fail "worktree $name is still registered in git"
  fi
  rm -rf "$wt"
fi
[ -d "$wt" ] && fail "folder of $name was not removed"
# The branch was made from main and has no commits of its own; -d deletes only a merged branch.
if git show-ref --verify --quiet "refs/heads/task/$name"; then
  git branch -d "task/$name" >> "$log" 2>&1 || fail "branch task/$name was not deleted"
fi

echo "log: $log"
[ "$result" -eq 0 ] || fail "fresh-checkout checks"
echo "VERIFY OK" | tee -a "$log"
